<?php require_once __DIR__."/config.php"; function user(){return $_SESSION["user"]??null;} function login_user($u){session_regenerate_id(true);$_SESSION["user"]=["id"=>(int)$u["id"],"name"=>$u["name"],"role"=>$u["role"]];} function logout_user(){$_SESSION=[];session_destroy();} function require_login(){if(!user())redirect("login.php");} function require_role($r){require_login();if(!in_array(user()["role"],$r,true)){http_response_code(403);exit("403 Forbidden");}} function cash_session(){if(!user())return null;$s=db()->prepare("SELECT * FROM cash_sessions WHERE user_id=? AND status='open' ORDER BY id DESC LIMIT 1");$s->execute([user()["id"]]);return $s->fetch()?:null;}